 void toggle(String label,String key,boolean value){Switch v=new Switch(this);v.setText(label);v.setTextSize(14);v.setTextColor(Color.rgb(228,237,222));v.setPadding(dp(4),dp(12),dp(4),dp(12));v.setChecked(value);v.setThumbTintList(ColorStateList.valueOf(Color.rgb(176,211,172)));v.setOnCheckedChangeListener((b,on)->storage.prefs.edit().putBoolean(key,on).apply());content.addView(v);}
 void build(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(16,24,19));scroll.setFitsSystemWindows(true);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(16),dp(20),dp(28));scroll.addView(content);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,insets)->{scroll.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});
  content.addView(button(t("‹ 返回","‹ Back"),this::finish));content.addView(text(t("设置","Settings"),27));section(t("语言与阅读","Language & reading"));content.addView(button(t("界面语言：","Language: ")+(storage.language().equals("zh")?"简体中文":"English"),()->new AlertDialog.Builder(this).setTitle(t("界面语言","Interface language")).setSingleChoiceItems(new String[]{"简体中文","English"},storage.language().equals("zh")?0:1,(d,index)->{storage.prefs.edit().putString("language",index==0?"zh":"en").apply();L10n.language=storage.language();d.dismiss();build();}).setNegativeButton(t("取消","Cancel"),null).show()));
  String[] modes={t("单页","Single page"),t("双页 · 左至右","Spread · Left to right"),t("双页 · 右至左","Spread · Right to left"),t("纵向连续","Vertical scrolling")};content.addView(button(t("新书默认模式：","Default for new books: ")+modes[storage.prefs.getInt("defaultMode",3)],()->new AlertDialog.Builder(this).setTitle(t("新书默认模式","Default for new books")).setSingleChoiceItems(modes,storage.prefs.getInt("defaultMode",3),(d,index)->{storage.prefs.edit().putInt("defaultMode",index).apply();d.dismiss();build();}).setNegativeButton(t("取消","Cancel"),null).show()));toggle(t("自动隐藏阅读工具栏","Auto-hide reading controls"),"autoHide",storage.prefs.getBoolean("autoHide",true));toggle(t("阅读时保持屏幕常亮","Keep screen awake while reading"),"keepAwake",storage.prefs.getBoolean("keepAwake",true));toggle(t("双页模式：封面独页","Spreads: show cover alone"),"cover",storage.prefs.getBoolean("cover",true));toggle(t("双页模式：横图独页","Spreads: show wide pages alone"),"wide",storage.prefs.getBoolean("wide",true));
  section(t("目录与缓存","Folders & cache"));content.addView(button(t("管理本地目录授权","Manage local folder access"),this::folders));content.addView(button(t("清理图片缓存","Clear image cache"),()->new AlertDialog.Builder(this).setTitle(t("清理缓存？","Clear cache?")).setMessage(t("不删除漫画、书签或阅读记录。","Comics, bookmarks and reading history stay untouched.")).setPositiveButton(t("清理","Clear"),(d,w)->{Images images=new Images(this);try{images.clear();storage.prefs.edit().putBoolean("cacheCleared",true).apply();Toast.makeText(this,t("缓存已清理","Cache cleared"),Toast.LENGTH_SHORT).show();}finally{images.close();}}).setNegativeButton(t("取消","Cancel"),null).show()));
  section(t("备份与迁移","Backup & migration"));content.addView(text(t("加密备份包含服务器授权、书签和阅读进度，不包含图片。恢复后请重新选择同一个本地目录。","Encrypted backups include server access, bookmarks and reading progress, but no images. Select the same local folders again after restoring."),13));content.addView(button(t("导出加密备份","Export encrypted backup"),()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/octet-stream");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"leaf-reader.lrbackup");startActivityForResult(i,20);}));content.addView(button(t("恢复加密备份","Restore encrypted backup"),()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,21);}));
  section(t("支持与关于","Support & about"));content.addView(button(t("支持 Leaf Reader  ♡","Support Leaf Reader  ♡"),this::support));content.addView(text(t("自愿赞助支持开发；所有阅读功能保持免费。","Voluntary support helps development; all reading features remain free."),13));content.addView(text("Leaf Reader 2.3.1 preview · ricefriend · MIT",12));
 }
 void folders(){List<String> trees=storage.trees();new AlertDialog.Builder(this).setTitle(t("移除授权，不删除文件","Remove access, keep files")).setItems(trees.toArray(new String[0]),(d,index)->{storage.removeTree(trees.get(index));storage.prefs.edit().putBoolean("sourcesChanged",true).apply();build();}).setNegativeButton(t("关闭","Close"),null).show();}
 void support(){String[] urls={SupportLinks.KOFI,SupportLinks.AFDIAN};List<String> labels=new ArrayList<>(),links=new ArrayList<>();if(!urls[0].isEmpty()){labels.add("Ko-fi");links.add(urls[0]);}if(!urls[1].isEmpty()){labels.add(L10n.t("爱发电 / Afdian"));links.add(urls[1]);}AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle(t("支持项目","Support the project"));if(labels.isEmpty())d.setMessage(t("赞助主页尚未开放。感谢你的使用、问题反馈和代码贡献！","Sponsorship pages are not open yet. Thank you for using Leaf Reader, reporting issues and contributing code!"));else d.setItems(labels.toArray(new String[0]),(x,index)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(links.get(index)))));d.setPositiveButton(t("关闭","Close"),null).show();}
 protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(result!=RESULT_OK||intent==null||intent.getData()==null)return;if(request==20||request==21)password(intent.getData(),request==20);}
 void password(Uri uri,boolean exporting){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);fields.setPadding(dp(24),dp(8),dp(24),dp(8));fields.addView(text(exporting?t("请牢记密码，没有密码无法恢复。","Keep this password safe; restoring requires it."):t("合并备份记录；同名记录将覆盖当前记录。目录需重新授权。","Merge backup data; matching records will replace current entries. Local folders need fresh permission."),13));EditText password=new EditText(this);password.setTag("backup-password");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setHint(t("备份密码（至少 8 个字符）","Backup password (at least 8 characters)"));fields.addView(password);EditText confirm=new EditText(this);if(exporting){confirm.setTag("backup-confirm");confirm.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);confirm.setHint(t("再次输入密码","Confirm password"));fields.addView(confirm);}AlertDialog dialog=new AlertDialog.Builder(this).setTitle(exporting?t("导出备份","Export backup"):t("恢复备份","Restore backup")).setView(fields).setPositiveButton(t("继续","Continue"),null).setNegativeButton(t("取消","Cancel"),null).create();passwordDialog=dialog;dialog.setOnShowListener(x->dialog.getButton(DialogInterface.BUTTON_POSITIVE).setOnClickListener(v->{String value=password.getText().toString();if(value.length()<8){password.setError(t("至少 8 个字符","At least 8 characters"));return;}if(exporting&&!value.equals(confirm.getText().toString())){confirm.setError(t("两次密码不一致","Passwords do not match"));return;}char[] secret=value.toCharArray();password.getText().clear();confirm.getText().clear();dialog.dismiss();working=true;Toast.makeText(this,t("正在处理备份…","Processing backup…"),Toast.LENGTH_SHORT).show();worker.submit(()->{String message;try{if(exporting){byte[] data=MigrationBackup.seal(storage.backupState(),secret);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(data);}message=t("备份已保存。换签名前请确认能使用该密码恢复。","Backup saved. Verify that it restores with your password before switching signatures.");}else{byte[] data;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();data=MigrationBackup.read(in);}storage.restoreState(MigrationBackup.open(data,secret));storage.prefs.edit().putBoolean("sourcesChanged",true).apply();message=t("备份已恢复。请重新授权本地目录；远程服务器可直接重连。","Backup restored. Authorize local folders again; remote servers can reconnect.");}}catch(Exception ex){message=ex.getMessage()==null?t("无法读写备份文件，请重新选择文件。","Cannot access the backup file. Select it again."):ex.getMessage();}finally{Arrays.fill(secret,'\0');}final String result=message;runOnUiThread(()->{working=false;if(closing)return;L10n.language=storage.language();build();new AlertDialog.Builder(this).setTitle(t("备份与迁移","Backup & migration")).setMessage(result).setPositiveButton(t("关闭","Close"),null).show();});});}));dialog.show();}
 public void onBackPressed(){if(!working)super.onBackPressed();else Toast.makeText(this,t("请等待备份完成","Wait for the backup to finish"),Toast.LENGTH_SHORT).show();}
 protected void onDestroy(){closing=true;worker.shutdown();super.onDestroy();}
